// Banner photography: responsive WebP files generated by scripts/optimize-images.mjs.
export const BANNER_WIDTHS = [480, 720, 1024, 1408] as const;
export const BANNER_KEYS = ['roads', 'ports', 'railways', 'metro', 'urban', 'logistics', 'semiconductor', 'highway-mountains', 'port-dusk'] as const;

export const isBanner = (key?: string | null): key is string => !!key && (BANNER_KEYS as readonly string[]).includes(key);
export const bannerSrc = (key: string, w: number = 1024) => `/assets/banners/${key}-${w}.webp`;
export const bannerSrcset = (key: string, widths: readonly number[] = BANNER_WIDTHS) => widths.map((w) => `${bannerSrc(key, w)} ${w}w`).join(', ');
/** JPG used for social sharing (og:image). */
export const bannerOg = (key?: string | null) => (isBanner(key) ? `/assets/banners/${key}-og.jpg` : undefined);
